const $=s=>document.querySelector(s),root=$('#content'),modal=$('#modal');const regions=['Kanto','Johto','Hoenn','Sinnoh','Unys','Kalos','Alola','Galar','Paldea'],bounds=[1,152,252,387,494,650,722,810,906,1026];const starters=[[1,4,7],[152,155,158],[252,255,258],[387,390,393],[495,498,501],[650,653,656],[722,725,728],[810,813,816],[906,909,912]];const names={1:'Bulbizarre',4:'Salamèche',7:'Carapuce',25:'Pikachu',133:'Évoli',152:'Germignon',155:'Héricendre',158:'Kaiminus',252:'Arcko',255:'Poussifeu',258:'Gobou',387:'Tortipouss',390:'Ouisticram',393:'Tiplouf',495:'Vipélierre',498:'Gruikui',501:'Moustillon',650:'Marisson',653:'Feunnec',656:'Grenousse',722:'Brindibou',725:'Flamiaou',728:'Otaquin',810:'Ouistempo',813:'Flambino',816:'Larméléon',906:'Poussacha',909:'Chochodile',912:'Coiffeton',94:'Ectoplasma',6:'Dracaufeu',150:'Mewtwo',384:'Rayquaza',249:'Lugia',487:'Giratina'};const sprite=id=>window.PMD_DATA?.[id]?.icon||(window.PMD_DATA?.[id]&&!window.PMD_DATA[id].remote?`assets/pmd/${id}/icon.png`:`https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/${id}.png`);const nm=id=>names[id]||`Pokémon #${String(id).padStart(3,'0')}`;const image=(id,cls='')=>`<img data-mon="${id}" class="${cls}" src="${sprite(id)}" alt="${nm(id)}" loading="lazy">`;let state;try{state=JSON.parse(localStorage.getItem('tour-infernale-v1'))}catch{}state=state||{owned:[],team:[],starter:null,survivor:null,tickets:Array(9).fill(3),coins:0,floor:1,kills:0,runs:0};let page='home',region=0,battle=null,run=null,anim=0,peer=null,connections=[],host=null,players=[],myId='local';const save=()=>{try{localStorage.setItem('tour-infernale-v1',JSON.stringify(state))}catch{toast('Sauvegarde indisponible : autorise le stockage du navigateur.')}wallet()};function wallet(){$('#tickets').textContent=state.tickets.reduce((a,b)=>a+b,0);$('#coins').textContent=state.coins}function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',3500)}function dialog(html){modal.innerHTML=`<button class="close" onclick="modal.close()">✕</button>${html}`;if(!modal.open)modal.showModal()}const head=(k,title,sub,tag='')=>`<div class="heading"><div><span class="eyebrow">${k}</span><h1>${title}</h1><p>${sub}</p></div>${tag?`<span class="tag">${tag}</span>`:''}</div>`;function nav(p){if(run&&run.active){finishRun();return}cancelAnimationFrame(anim);page=p;document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===p));$('#crumb').textContent=({home:'La tour',survival:'Survie',gacha:'Invocations',collection:'Mes Pokémon',team:'Mon équipe',friends:'Jouer entre amis',inventory:'Sac & objets'})[p];({home:homePage,survival:survivalPage,gacha:gachaPage,collection:collectionPage,team:teamPage,friends:friendsPage})[p]();wallet()}document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>nav(b.dataset.page));$('#settings').onclick=()=>dialog('<h2>Ton aventure</h2><p>Progression enregistrée sur ce navigateur. Pas de compte ni de paiement.</p><p>Survie : ZQSD / WASD / flèches, ou glisser le doigt. Attaques automatiques. Échap pour mettre en pause.</p><p>Tour : un actif par joueur et cinq remplaçants. Le boss cible un seul actif par tour.</p><button onclick="exportSave()">Exporter ma sauvegarde</button>');function exportSave(){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(state)],{type:'application/json'}));a.download='tour-infernale-sauvegarde.json';a.click();URL.revokeObjectURL(a.href)}function requireStarter(){if(!state.starter){starterModal();return false}return true}function cards(ids,action,selected=[]){return ids.map(id=>`<button class="poke ${selected.includes(id)?'selected':''}" onclick="${action}(${id})">${image(id)}<small>#${String(id).padStart(3,'0')}</small><strong>${nm(id)}</strong></button>`).join('')}function starterModal(){dialog(`<span class="eyebrow">LE DÉBUT D'UNE LÉGENDE</span><h2>Choisis ton premier partenaire</h2><p>Les 27 starters des neuf générations, ainsi que Pikachu et Évoli.</p><div class="tabs">${regions.map((r,i)=>`<button onclick="starterRegion(${i})">${r}</button>`).join('')}</div><div class="grid" id="starterGrid">${cards([...starters[0],25,133],'chooseStarter')}</div>`)}function starterRegion(i){$('#starterGrid').innerHTML=cards([...starters[i],...(i===0?[25,133]:[])],'chooseStarter')}function chooseStarter(id){if(state.starter)return;state.starter=id;state.survivor=id;state.owned=[id];state.team=[id];save();modal.close();nav('home');toast(`${nm(id)} rejoint ton aventure !`)}function homePage(){const boss=bossAt(state.floor);root.innerHTML=head('LE SOMMET N’ATTEND QUE TOI','La Tour Infernale','Rassemble ton équipe. Défie les gardiens. Écris ta légende.','✦ SAISON 01 · LES ORIGINES')+`<section class="hero"><canvas id="landscape"></canvas><div class="hero-copy"><span class="eyebrow">UNE ASCENSION SANS FIN</span><h2>PLUS HAUT.<br>PLUS FORT.<br>ENSEMBLE.</h2><p>Des boss toujours plus redoutables.<br>Six Pokémon par dresseur. Jusqu’à quatre amis.<br>Jusqu’où irez-vous ?</p><button class="primary" onclick="${state.starter?'startBattle()':'starterModal()'}">${state.starter?'Entrer dans la tour':'Choisir mon starter'} <span>↗</span></button></div><div class="hero-meta">ÉTAGE ${String(state.floor).padStart(2,'0')} / ∞ &nbsp; · &nbsp; ${nm(boss)}</div></section><div class="stats"><div class="stat"><i>♜</i><div><small>Prochain étage</small><strong>${String(state.floor).padStart(2,'0')} <small>/ ∞</small></strong></div></div><div class="stat"><i>◉</i><div><small>Pokémon collectionnés</small><strong>${state.owned.length} <small>/ 1 025</small></strong></div></div><div class="stat"><i>✧</i><div><small>Pokémon vaincus en survie</small><strong>${state.kills}</strong></div></div></div><div class="columns"><section class="card"><div class="section-head"><h2>Les prochains gardiens</h2><small>L’ASCENSION ↗</small></div>${[0,1,2].map((v)=>`<div class="boss-row">${image(bossAt(state.floor+v))}<div><h3>${nm(bossAt(state.floor+v))}</h3><p>${v===0?'Prochain défi':'Gardien de la tour'} · Niveau ${10+(state.floor+v)*3}</p></div><b>ÉTAGE ${String(state.floor+v).padStart(2,'0')}</b></div>`).join('')}</section><section class="card"><div class="section-head"><h2>Ton équipe</h2><small>${state.team.length} / 6</small></div><p class="help">Un partenaire actif. Cinq en réserve.<br>Chaque choix peut changer le combat.</p><div class="team-preview">${state.team.map(id=>image(id)).join('')}${Array.from({length:6-state.team.length},()=>'<div class="empty-slot">+</div>').join('')}</div><button class="wide" onclick="nav('team')">Préparer mon équipe →</button><p class="help">✧ Besoin de renforts ? <a href="#" style="color:var(--lime)" onclick="nav('survival');return false">Gagne des tickets en survie.</a></p></section></div>`;landscape()}
function bossAt(f){return [94,6,249,150,384,487][(f-1)%6]}function landscape(){const c=$('#landscape'),x=c.getContext('2d');c.width=800;c.height=320;let seed=42;const rnd=()=>((seed=(seed*1664525+1013904223)>>>0)/4294967296);x.fillStyle='#263a40';x.fillRect(0,0,800,320);for(let i=0;i<90;i++){x.fillStyle='#acb19b';x.fillRect(rnd()*800,rnd()*180,1,1)}x.fillStyle='#bdcaa5';x.fillRect(663,32,42,42);x.fillStyle='#263a40';x.fillRect(653,22,31,38);for(let l=0;l<3;l++){x.fillStyle=['#294348','#203a39','#172f2d'][l];for(let i=0;i<22;i++){const xx=i*42,yy=115+rnd()*45+l*35;x.beginPath();x.moveTo(xx-60,320);x.lineTo(xx,yy);x.lineTo(xx+70,320);x.fill()}}x.fillStyle='#111d22';x.fillRect(495,65,100,230);x.fillRect(484,52,122,20);for(let i=0;i<5;i++)x.fillRect(484+i*27,36,14,25);x.fillRect(480,282,130,38);for(let y=70;y<280;y+=18){x.fillStyle=y%36?'#1c2b2d':'#243334';x.fillRect(497,y,96,2);for(let z=0;z<4;z++){x.fillStyle='#34413a';x.fillRect(500+z*25+(y%36?0:12),y+4,1,12)}}for(let y=85;y<255;y+=47){x.fillStyle='#efb46d';x.fillRect(537,y,15,25);x.fillStyle='#694d35';x.fillRect(542,y,5,25)}x.fillStyle='#080f13';x.fillRect(530,270,30,45);for(let i=0;i<75;i++){x.fillStyle=['#41634a','#263f35','#63815b'][i%3];const xx=rnd()*800,yy=270+rnd()*50;x.fillRect(xx,yy,15,5);x.fillRect(xx+4,yy-6,5,15)}for(let i=0;i<24;i++){x.fillStyle='#efa764';x.fillRect(440+rnd()*220,80+rnd()*220,2,2)}}
function teamPage(){if(!requireStarter())return;root.innerHTML=head('PRÉPARATION','Une équipe pour le sommet','Sélectionne jusqu’à six Pokémon pour la tour. Ton Pokémon de survie se choisit séparément.')+`<div class="card"><h2>Équipe de la tour · ${state.team.length}/6</h2><p>Clique pour ajouter ou retirer un Pokémon. Tu peux entrer avec moins de six le temps de compléter ton équipe.</p><div class="grid">${cards(state.owned,'toggleTeam',state.team)}</div></div>`}function toggleTeam(id){if(state.team.includes(id)){if(state.team.length===1)return toast('Garde au moins un Pokémon dans ton équipe.');state.team=state.team.filter(v=>v!==id)}else{if(state.team.length===6)return toast('Ton équipe compte déjà six Pokémon.');state.team.push(id)}save();teamPage()}function collectionPage(){root.innerHTML=head('POKÉDEX','Mes Pokémon',`${state.owned.length} partenaires découverts. Tes doublons deviennent des fragments ✦.`)+`<div class="grid">${cards(state.owned,'inspect')}</div>`;if(!state.owned.length)root.innerHTML+='<button class="primary" onclick="starterModal()">Choisir mon starter</button>'}async function inspect(id){dialog(`<h2>${nm(id)}</h2><div class="result">${image(id)}</div><p>Chargement des données Pokémon…</p>`);try{const p=await getPokemon(id);dialog(`<h2>${nm(id)}</h2><div class="result">${image(id)}</div><p>Types : ${p.types.join(' / ')} · PV de base : ${p.hp} · Attaque : ${p.atk} · Vitesse : ${p.speed}</p><p>Attaques : ${p.moves.map(m=>m.name).join(', ')}</p>`)}catch{toast('Données indisponibles. Vérifie ta connexion.')}}
function gachaPage(){root.innerHTML=head('UN NOUVEAU PARTENAIRE T’ATTEND','Invocations régionales','Neuf générations, neuf bannières. Les tickets se gagnent en survie et dans la tour.')+`<div class="tabs">${regions.map((r,i)=>`<button class="${region===i?'active':''}" onclick="region=${i};gachaPage()">${r} <small>· ${state.tickets[i]}</small></button>`).join('')}</div><section class="banner">${image([150,249,384,487,643,716,791,888,1007][region])}<span class="eyebrow">GÉNÉRATION ${region+1} · ${regions[region].toUpperCase()}</span><h2>L’appel de ${regions[region]}</h2><p>Tous les Pokémon de cette génération dans un tirage équiprobable. Aucun achat, aucune monnaie réelle.</p><button class="primary" onclick="pull()">Invoquer · 1 ticket ${regions[region]}</button><p class="help">${state.tickets[region]} tickets disponibles · Chance par espèce : ${(100/(bounds[region+1]-bounds[region])).toFixed(2)} %</p></section><div class="card" style="margin-top:20px"><h2>Chaque aventure te rapproche d’eux.</h2><p>Survis 20 secondes pour un ticket de la région choisie. Les éliminations rapportent des fragments, et chaque boss vaincu offre deux tickets régionaux.</p><button onclick="nav('survival')">Partir en expédition →</button></div>`}function pull(){if(!requireStarter())return;if(state.tickets[region]<1)return toast('Gagne des tickets de cette région en survie.');state.tickets[region]--;const id=bounds[region]+Math.floor(Math.random()*(bounds[region+1]-bounds[region]));const dup=state.owned.includes(id);if(dup)state.coins+=30;else state.owned.push(id);ensurePmd(id);save();gachaPage();dialog(`<div class="result"><span class="eyebrow">${dup?'UN VISAGE FAMILIER':'NOUVEAU PARTENAIRE'}</span><h2>${nm(id)}</h2>${image(id)}<p>${dup?'+30 fragments pour ce doublon.':'Ton nouveau Pokémon a rejoint la collection.'}</p><button class="primary" onclick="modal.close();nav('team')">Préparer mon équipe</button></div>`);fetch(`https://pokeapi.co/api/v2/pokemon-species/${id}`).then(r=>r.json()).then(p=>{names[id]=p.names.find(n=>n.language.name==='fr')?.name||p.name;if(modal.open)modal.querySelector('h2').textContent=nm(id)}).catch(()=>{})}
const cache={};async function getPokemon(id){if(cache[id])return cache[id];const p=await fetch(`https://pokeapi.co/api/v2/pokemon/${id}`).then(r=>{if(!r.ok)throw Error();return r.json()});const stats=Object.fromEntries(p.stats.map(s=>[s.stat.name,s.base_stat]));let ms=await Promise.all(p.moves.slice().sort(()=>Math.random()-.5).slice(0,12).map(async z=>{try{const m=await fetch(z.move.url).then(r=>r.json());return m.power&&m.damage_class.name!=='status'?{name:m.names.find(n=>n.language.name==='fr')?.name||m.name,type:m.type.name,power:m.power,accuracy:m.accuracy||100,pp:m.pp,category:m.damage_class.name}:null}catch{return null}}));ms=ms.filter(Boolean).slice(0,4);if(!ms.length)ms=[{name:'Charge',type:'normal',power:40,accuracy:100,pp:35,category:'physical'}];return cache[id]={id,hp:stats.hp,atk:stats.attack,def:stats.defense,spa:stats['special-attack'],spd:stats['special-defense'],speed:stats.speed,types:p.types.map(t=>t.type.name),moves:ms}}
const chart={normal:{rock:.5,ghost:0,steel:.5},fire:{grass:2,ice:2,bug:2,steel:2,fire:.5,water:.5,rock:.5,dragon:.5},water:{fire:2,ground:2,rock:2,water:.5,grass:.5,dragon:.5},grass:{water:2,ground:2,rock:2,fire:.5,grass:.5,poison:.5,flying:.5,bug:.5,dragon:.5,steel:.5},electric:{water:2,flying:2,electric:.5,grass:.5,dragon:.5,ground:0},ice:{grass:2,ground:2,flying:2,dragon:2,fire:.5,water:.5,ice:.5,steel:.5},fighting:{normal:2,ice:2,rock:2,dark:2,steel:2,poison:.5,flying:.5,psychic:.5,bug:.5,fairy:.5,ghost:0},poison:{grass:2,fairy:2,poison:.5,ground:.5,rock:.5,ghost:.5,steel:0},ground:{fire:2,electric:2,poison:2,rock:2,steel:2,grass:.5,bug:.5,flying:0},flying:{grass:2,fighting:2,bug:2,electric:.5,rock:.5,steel:.5},psychic:{fighting:2,poison:2,psychic:.5,steel:.5,dark:0},bug:{grass:2,psychic:2,dark:2,fire:.5,fighting:.5,poison:.5,flying:.5,ghost:.5,steel:.5,fairy:.5},rock:{fire:2,ice:2,flying:2,bug:2,fighting:.5,ground:.5,steel:.5},ghost:{psychic:2,ghost:2,dark:.5,normal:0},dragon:{dragon:2,steel:.5,fairy:0},dark:{psychic:2,ghost:2,fighting:.5,dark:.5,fairy:.5},steel:{ice:2,rock:2,fairy:2,fire:.5,water:.5,electric:.5,steel:.5},fairy:{fighting:2,dragon:2,dark:2,fire:.5,poison:.5,steel:.5}};function damage(a,d,m){if(Math.random()*100>m.accuracy)return {n:0,msg:'L’attaque échoue !'};let eff=d.types.reduce((n,t)=>n*(chart[m.type]?.[t]??1),1),special=m.category==='special',n=Math.floor(((2*20/5+2)*m.power*(special?a.spa:a.atk)/Math.max(1,special?d.spd:d.def)/50+2)*(a.types.includes(m.type)?1.5:1)*eff*(.85+Math.random()*.15));return{n:eff===0?0:Math.max(1,n),msg:eff===0?'Sans effet.':eff>1?'Super efficace !':eff<1?'Peu efficace…':''}}
async function startBattle(){if(!requireStarter())return;if(host){host.send({type:'ready',team:state.team});return toast('Équipe envoyée. L’hôte lance le combat.')}if(!state.team.length)return toast('Prépare ton équipe.');root.innerHTML=head('LA TOUR','Préparation du combat…','Chargement des statistiques, des types et des attaques Pokémon.');try{const parties=[{pid:myId,name:'Toi',ids:state.team},...players].slice(0,4);const teams=await Promise.all(parties.map(async p=>({...p,active:0,mons:await Promise.all(p.ids.slice(0,6).map(async id=>{let d=await getPokemon(id);const held=heldItem(id)||{};const max=Math.round((60+d.hp)*(1+(held.hp||0)));return {...d,atk:Math.round(d.atk*(1+(held.atk||0))),spa:Math.round(d.spa*(1+(held.atk||0))),def:Math.round(d.def*(1+(held.def||0))),spd:Math.round(d.spd*(1+(held.def||0))),speed:Math.round(d.speed*(1+(held.speed||0))),regen:held.regen||0,max,hp:max,moves:d.moves.map(m=>({...m,left:m.pp}))}}))})));let b=await getPokemon(bossAt(state.floor));battle={teams,boss:{...b,max:(150+state.floor*65)*teams.length,hp:(150+state.floor*65)*teams.length},log:['Le gardien apparaît. À vous de jouer !'],turn:1,actions:{},over:false};syncBattle();renderBattle()}catch{toast('Impossible de charger les données Pokémon. Réessaie avec une connexion Internet.');nav('home')}}function syncBattle(){connections.forEach(c=>c.open&&c.send({type:'battle',battle}))}function renderBattle(){if(!battle)return;cancelAnimationFrame(anim);const me=battle.teams.find(t=>t.pid===myId)||battle.teams[0],mon=me.mons[me.active];if(mon.moves.every(m=>m.left<=0))mon.moves=[{name:'Lutte',type:'normal',power:50,accuracy:100,pp:999,left:999,category:'physical'}];root.innerHTML=head('ÉTAGE '+state.floor,'Face au gardien',`Tour ${battle.turn} · Choisis une attaque ou change de Pokémon.`,battle.over?'COMBAT TERMINÉ':'COMBAT AU TOUR PAR TOUR')+`<section class="arena"><div class="boss-hud"><strong>${nm(battle.boss.id)}</strong><div class="bar"><div style="width:${100*battle.boss.hp/battle.boss.max}%"></div></div><small>${battle.boss.hp} / ${battle.boss.max} PV</small></div>${image(battle.boss.id,'boss-sprite')}<div class="allies">${battle.teams.map(t=>{const p=t.mons[t.active];return`<div class="ally">${image(p.id)}<div>${t.pid===myId?'Toi':t.name}</div><small>${nm(p.id)} · ${p.hp}/${p.max} PV</small><div class="bar"><div style="width:${p.hp/p.max*100}%"></div></div></div>`}).join('')}</div></section><div class="moves">${mon.moves.map((m,i)=>`<button ${battle.over||battle.actions[myId]||!m.left||!mon.hp?'disabled':''} onclick="act({move:${i}})">${m.name}<small>${m.type} · Puiss. ${m.power} · PP ${m.left}/${m.pp}</small></button>`).join('')}</div><div class="battle-team">${me.mons.map((p,i)=>`<button class="${me.active===i?'active':''}" ${!p.hp||battle.over||battle.actions[myId]?'disabled':''} onclick="act({swap:${i}})">${image(p.id)}<small>${p.hp}/${p.max}</small></button>`).join('')}</div><div class="card log" style="margin-top:16px">${battle.log.slice(-6).map(l=>`<div>${l}</div>`).join('')}</div>${battle.over?'<button class="primary" style="margin-top:15px" onclick="nav(\'home\')">Retour à la tour →</button>':''}`}
function act(action){if(!battle||battle.over)return;if(host){host.send({type:'action',action});battle.actions[myId]=action;renderBattle();return}battle.actions[myId]=action;resolveTurn()}function resolveTurn(){const alive=battle.teams.filter(t=>t.mons.some(m=>m.hp>0));if(!alive.every(t=>battle.actions[t.pid])){syncBattle();renderBattle();return}battle.fx=[];battle.fxSerial=(battle.fxSerial||0)+1;for(const t of alive){const a=battle.actions[t.pid];if(a.swap!==undefined){if(t.mons[a.swap]?.hp>0){t.active=a.swap;battle.log.push(`${t.name} envoie ${nm(t.mons[t.active].id)}.`)}}}const turns=alive.filter(t=>battle.actions[t.pid].move!==undefined).map(t=>({t,original:t.active,speed:t.mons[t.active].speed}));turns.push({boss:true,speed:battle.boss.speed});turns.sort((a,b)=>b.speed-a.speed);for(const turn of turns){if(battle.boss.hp<=0)break;if(turn.boss){const targets=battle.teams.filter(t=>t.mons[t.active].hp>0);if(!targets.length)break;const target=targets[Math.floor(Math.random()*targets.length)],p=target.mons[target.active],m=battle.boss.moves[Math.floor(Math.random()*battle.boss.moves.length)],r=damage(battle.boss,p,m);p.hp=Math.max(0,p.hp-r.n);queueBattleFx(m.type,'boss',battle.teams.indexOf(target),r.n);battle.log.push(`${nm(battle.boss.id)} utilise ${m.name} sur ${nm(p.id)} (${target.name}) : −${r.n} PV. ${r.msg}`);if(!p.hp){battle.log.push(`${nm(p.id)} est K.O. !`);const next=target.mons.findIndex(v=>v.hp>0);if(next>=0)target.active=next}}else{const t=turn.t,p=t.mons[t.active];if(!p.hp||t.active!==turn.original)continue;const m=p.moves[battle.actions[t.pid].move];if(!m||m.left<=0)continue;m.left--;const r=damage(p,battle.boss,m);battle.boss.hp=Math.max(0,battle.boss.hp-r.n);queueBattleFx(m.type,battle.teams.indexOf(t),'boss',r.n);battle.log.push(`${nm(p.id)} utilise ${m.name} : −${r.n} PV. ${r.msg}`)}}for(const t of battle.teams){const p=t.mons[t.active];if(p.hp>0&&p.regen)p.hp=Math.min(p.max,p.hp+Math.ceil(p.regen*3))}battle.turn++;battle.actions={};if(!battle.boss.hp){battle.over=true;battle.win=true;battle.log.push('Victoire ! Étage suivant débloqué. +2 tickets régionaux et 50 fragments.');rewardBattle();connections.forEach(c=>c.open&&c.send({type:'reward'}))}else if(!battle.teams.some(t=>t.mons.some(p=>p.hp>0))){battle.over=true;battle.log.push('Ton équipe est K.O. Prépare une nouvelle stratégie et réessaie.')}syncBattle();renderBattle()}function rewardBattle(){state.floor++;state.tickets[(state.floor-2)%9]+=2;state.coins+=50;save()}
function survivalPage(){if(!requireStarter())return;root.innerHTML=head('EXPÉDITION','Les clairières sauvages','Un seul Pokémon. Des vagues sans fin. Des tickets pour ta prochaine invocation.','SURVIE · SOLO')+`<section class="card"><h2>Choisis ton unique partenaire</h2><div class="grid">${cards(state.owned,'selectSurvivor',[state.survivor])}</div><h3>Région des tickets</h3><div class="tabs">${regions.map((r,i)=>`<button class="${region===i?'active':''}" onclick="region=${i};survivalPage()">${r}</button>`).join('')}</div><p>Un ticket toutes les 20 secondes. Récupère les cristaux d’expérience pour améliorer ta puissance, ta cadence ou ta vitesse. Les attaques visent automatiquement l’ennemi le plus proche.</p><button class="primary" onclick="startRun()">Entrer dans la clairière →</button><p class="help">ZQSD / WASD / flèches · Sur mobile, glisse le doigt · Échap : pause</p></section>`}function selectSurvivor(id){state.survivor=id;save();survivalPage()}const keys={};addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key)&&run?.active)e.preventDefault();keys[e.key.toLowerCase()]=true;if(e.key==='Escape'&&run?.active){togglePause()}});addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);addEventListener('blur',()=>{Object.keys(keys).forEach(k=>delete keys[k]);if(run?.active){run.pause=true;run.joy=null}});let images={};function img(id){if(!images[id]){images[id]=new Image();images[id].src=sprite(id)}return images[id]}function startRun(){run={active:true,pause:false,x:450,y:260,hp:100,time:0,kills:0,enemies:[],bullets:[],gems:[],xp:0,level:1,next:5,power:25,cadence:.65,speed:155,spawn:0,shoot:0,reward:0,region,joy:null};root.innerHTML=head('EXPÉDITION · '+regions[region],'Survis à la horde','Un seul partenaire. Fais de chaque seconde un ticket de plus.')+`<div class="run-hud"><b id="runTime">00:00</b><span id="runHealth">♥ 100</span><span id="runLevel">Niv. 1</span><span id="runKills">0 éliminations</span><button style="margin-left:auto" onclick="run.pause=!run.pause">⏯</button><button onclick="finishRun()">Extraire</button></div><canvas id="survive" width="900" height="520"></canvas><p class="help">Déplace-toi pour esquiver et ramasser les cristaux. Attaques automatiques · 1 ticket / 20 secondes · Échap pour reprendre après une pause.</p>`;const c=$('#survive');c.onpointerdown=e=>{c.setPointerCapture(e.pointerId);const r=c.getBoundingClientRect();run.joy={x:(e.clientX-r.left)/r.width*900,y:(e.clientY-r.top)/r.height*520}};c.onpointermove=e=>{if(e.buttons){const r=c.getBoundingClientRect();run.joy={x:(e.clientX-r.left)/r.width*900,y:(e.clientY-r.top)/r.height*520}}};c.onpointerup=c.onpointercancel=()=>run.joy=null;let last=performance.now();function frame(now){if(!run?.active)return;const dt=Math.min(.04,(now-last)/1000);last=now;if(!run.pause)updateRun(dt);drawRun(c);anim=requestAnimationFrame(frame)}anim=requestAnimationFrame(frame)}function updateRun(dt){const r=run;r.time+=dt;let dx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.q||keys.arrowleft?1:0),dy=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.z||keys.arrowup?1:0);if(r.joy){dx=r.joy.x-r.x;dy=r.joy.y-r.y;if(Math.hypot(dx,dy)<8)dx=dy=0}let len=Math.hypot(dx,dy)||1;r.x=Math.max(24,Math.min(876,r.x+dx/len*r.speed*dt));r.y=Math.max(24,Math.min(496,r.y+dy/len*r.speed*dt));r.spawn-=dt;if(r.spawn<=0){r.spawn=Math.max(.15,.9-r.time/160);let edge=Math.floor(Math.random()*4);r.enemies.push({x:edge===0?-20:edge===1?920:Math.random()*900,y:edge===2?-20:edge===3?540:Math.random()*520,hp:40+r.time*.7,id:bounds[r.region]+Math.floor(Math.random()*(bounds[r.region+1]-bounds[r.region])),speed:30+r.time*.3})}r.shoot-=dt;if(r.shoot<=0&&r.enemies.length){r.shoot=r.cadence;const e=r.enemies.reduce((a,b)=>Math.hypot(a.x-r.x,a.y-r.y)<Math.hypot(b.x-r.x,b.y-r.y)?a:b),l=Math.hypot(e.x-r.x,e.y-r.y)||1;r.bullets.push({x:r.x,y:r.y,dx:(e.x-r.x)/l*430,dy:(e.y-r.y)/l*430,life:2})}for(const e of r.enemies){let l=Math.hypot(e.x-r.x,e.y-r.y)||1;e.x+=(r.x-e.x)/l*e.speed*dt;e.y+=(r.y-e.y)/l*e.speed*dt;if(l<25)r.hp-=22*dt}for(const b of r.bullets){b.x+=b.dx*dt;b.y+=b.dy*dt;b.life-=dt;for(const e of r.enemies)if(e.hp>0&&b.life>0&&Math.hypot(e.x-b.x,e.y-b.y)<23){e.hp-=r.power;b.life=0;if(e.hp<=0){r.kills++;r.gems.push({x:e.x,y:e.y})}}}r.bullets=r.bullets.filter(b=>b.life>0);r.enemies=r.enemies.filter(e=>e.hp>0);r.gems=r.gems.filter(g=>{if(Math.hypot(g.x-r.x,g.y-r.y)<37){r.xp++;return false}return true});if(r.xp>=r.next){r.xp-=r.next;r.level++;r.next+=4;r.pause=true;dialog(`<h2>Niveau ${r.level} !</h2><p>Choisis ton amélioration.</p><div class="level-up"><button onclick="upgrade('power')">✦ Puissance<br>+15 dégâts</button><button onclick="upgrade('cadence')">↯ Cadence<br>+20 %</button><button onclick="upgrade('speed')">➤ Vitesse<br>+20 %</button></div>`)}if(r.hp<=0)finishRun();if(!r.active)return;$('#runTime').textContent=`${String(Math.floor(r.time/60)).padStart(2,'0')}:${String(Math.floor(r.time%60)).padStart(2,'0')}`;$('#runHealth').textContent='♥ '+Math.ceil(r.hp);$('#runLevel').textContent=`Niv. ${r.level} · XP ${r.xp}/${r.next}`;$('#runKills').textContent=r.kills+' éliminations'}function upgrade(type){if(!run?.active)return;if(type==='power')run.power+=15;if(type==='cadence')run.cadence=Math.max(.12,run.cadence*.8);if(type==='speed')run.speed*=1.2;run.pause=false;modal.close()}function drawRun(c){const x=c.getContext('2d'),r=run;x.fillStyle='#223b2a';x.fillRect(0,0,900,520);for(let i=0;i<450;i++){let a=(i*127)%900,b=(i*83)%520;x.fillStyle=i%5?'#2a452f':'#466044';x.fillRect(a,b,3,3)}x.strokeStyle='#314b31';x.lineWidth=32;x.beginPath();x.moveTo(0,390);x.bezierCurveTo(300,200,500,500,900,160);x.stroke();for(const g of r.gems){x.fillStyle='#8be8dd';x.fillRect(g.x-4,g.y-4,8,8)}for(const e of r.enemies){const im=img(e.id);if(im.complete&&im.naturalWidth)x.drawImage(im,e.x-28,e.y-28,56,56);else{x.fillStyle='#bc8675';x.fillRect(e.x-12,e.y-12,24,24)}}for(const b of r.bullets){x.fillStyle='#f1dda0';x.fillRect(b.x-4,b.y-4,8,8)}x.fillStyle='#0005';x.beginPath();x.ellipse(r.x,r.y+18,22,8,0,0,7);x.fill();const im=img(state.survivor);if(im.complete&&im.naturalWidth)x.drawImage(im,r.x-36,r.y-36,72,72);x.strokeStyle='#d3ee89';x.strokeRect(r.x-27,r.y-29,54,57);if(r.pause){x.fillStyle='#0b1717aa';x.fillRect(0,0,900,520);x.fillStyle='#d3ee89';x.font='28px monospace';x.textAlign='center';x.fillText('PAUSE',450,250)}}function finishRun(){if(!run?.active)return;run.active=false;cancelAnimationFrame(anim);const tickets=Math.floor(run.time/20);state.tickets[run.region]+=tickets;state.coins+=run.kills;state.kills+=run.kills;state.runs++;save();if(modal.open)modal.close();root.innerHTML=head('EXPÉDITION TERMINÉE','De retour au camp',`${Math.floor(run.time)} secondes de survie · ${run.kills} éliminations · Niveau ${run.level}`)+`<div class="card result"><h2>Ton butin</h2>${image(state.survivor)}<h1>+${tickets} tickets ${regions[run.region]}</h1><p>+${run.kills} fragments · Progression sauvegardée</p><button class="primary" onclick="nav('gacha')">Invoquer un Pokémon</button> <button onclick="nav('survival')">Repartir</button></div>`}
function friendsPage(){root.innerHTML=head('L’UNION FAIT LA FORCE','À plusieurs, plus haut','Formez un groupe de quatre dresseurs maximum. Chacun apporte son équipe de six.')+`<div class="columns"><div class="card"><h2>Créer un salon</h2><p>Connexion directe entre navigateurs via PeerJS. L’hôte doit garder cette page ouverte. La survie se joue en solo dans cette version.</p><button class="primary" onclick="createRoom()">Créer mon salon</button><div id="roomInfo"></div></div><div class="card"><h2>Rejoindre des amis</h2><p>Demande le code du salon à ton ami.</p><input id="roomCode" placeholder="Code du salon" aria-label="Code du salon"><button onclick="joinRoom()">Rejoindre →</button><p class="help">La connexion dépend du réseau et du service de signalisation PeerJS. Les réseaux restrictifs peuvent la bloquer.</p><div id="joinStatus"></div></div></div>`;if(peer?.id&&!host)roomInfo()}function safe(t){return String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function roomInfo(){if($('#roomInfo'))$('#roomInfo').innerHTML=`<p>Code : <strong style="color:var(--lime)">${safe(peer.id)}</strong></p><button onclick="navigator.clipboard.writeText(peer.id).then(()=>toast('Code copié')).catch(()=>toast('Sélectionne le code pour le copier'))">Copier</button><p>${1+players.length}/4 dresseurs connectés · Équipes reçues : ${players.length}</p><button class="primary" onclick="startBattle()">Lancer le raid</button>`}function initPeer(){if(typeof Peer==='undefined'){toast('Le service multijoueur est indisponible.');return null}if(peer)peer.destroy();connections=[];players=[];host=null;peer=new Peer();peer.on('error',e=>toast('Connexion : '+e.type));peer.on('disconnected',()=>toast('Service déconnecté. Recrée ou rejoins le salon.'));return peer}function createRoom(){if(!requireStarter())return;const p=initPeer();if(!p)return;p.on('open',id=>{myId=id;roomInfo()});p.on('connection',c=>{if(connections.length>=3){c.on('open',()=>{c.send({type:'full'});setTimeout(()=>c.close(),300)});return}connections.push(c);c.on('data',d=>{if(d.type==='ready'&&Array.isArray(d.team)){const ids=[...new Set(d.team)].filter(id=>Number.isInteger(id)&&id>=1&&id<=1025).slice(0,6);players=players.filter(v=>v.pid!==c.peer);if(ids.length)players.push({pid:c.peer,name:'Allié '+(players.length+1),ids});roomInfo()}if(d.type==='action'&&battle&&!battle.over&&battle.teams.some(t=>t.pid===c.peer)){const me=battle.teams.find(t=>t.pid===c.peer);if(d.action?.swap!==undefined&&me.mons[d.action.swap]?.hp>0||Number.isInteger(d.action?.move)&&me.mons[me.active].moves[d.action.move]?.left>0){battle.actions[c.peer]=d.action;resolveTurn()}}});c.on('close',()=>{connections=connections.filter(v=>v!==c);players=players.filter(v=>v.pid!==c.peer);if(battle&&!battle.over){battle.teams=battle.teams.filter(t=>t.pid!==c.peer);battle.log.push('Un allié a quitté le combat.');resolveTurn()}roomInfo()})})}function joinRoom(){if(!requireStarter())return;const code=$('#roomCode').value.trim();if(!code)return toast('Saisis un code de salon.');const p=initPeer();if(!p)return;$('#joinStatus').textContent='Connexion en cours…';p.on('open',id=>{myId=id;host=p.connect(code,{reliable:true});host.on('open',()=>{host.send({type:'ready',team:state.team});if($('#joinStatus'))$('#joinStatus').textContent='Connecté ! Équipe envoyée, en attente de l’hôte.'});host.on('data',d=>{if(d.type==='full')toast('Ce salon est complet.');if(d.type==='battle'){battle=d.battle;renderBattle()}if(d.type==='reward')rewardBattle()});host.on('close',()=>{host=null;battle=null;toast('Le salon a été fermé par l’hôte.');nav('friends')})})}